-- Additive operational schema. No consumption or financial accounts in this delivery.
ALTER TABLE restaurant.role_permissions DROP CONSTRAINT role_permissions_permission_check;
ALTER TABLE restaurant.role_permissions ADD CONSTRAINT role_permissions_permission_check CHECK(permission IN ('usuarios.gestionar','roles.gestionar','locales.asignar','auditoria.consultar','carta.consultar','carta.gestionar','stock.ajustar','salon.gestionar','mesas.operar'));
DO $upgrade$ DECLARE a record; r uuid; BEGIN
FOR a IN SELECT u.id,u.tenant_id FROM restaurant.users u JOIN restaurant.user_roles ur ON ur.tenant_id=u.tenant_id AND ur.user_id=u.id JOIN restaurant.role_permissions rp ON rp.tenant_id=ur.tenant_id AND rp.role_id=ur.role_id WHERE u.active AND rp.permission IN ('usuarios.gestionar','roles.gestionar','locales.asignar','auditoria.consultar') GROUP BY u.id,u.tenant_id HAVING count(DISTINCT rp.permission)=4 LOOP
r:=gen_random_uuid();
INSERT INTO restaurant.roles(id,tenant_id,name) VALUES(r,a.tenant_id,'Operación migrada '||a.id::text);
INSERT INTO restaurant.role_permissions(tenant_id,role_id,permission) SELECT a.tenant_id,r,p FROM unnest(ARRAY['carta.consultar','carta.gestionar','stock.ajustar','salon.gestionar','mesas.operar']) p;
INSERT INTO restaurant.user_roles VALUES(a.tenant_id,a.id,r);
UPDATE restaurant.sessions SET revoked=true WHERE tenant_id=a.tenant_id AND user_id=a.id;
INSERT INTO restaurant.audit_events(id,tenant_id,actor_id,action,entity_id,outcome) VALUES(gen_random_uuid(),a.tenant_id,NULL,'permissions.upgrade004',a.id,'success');
END LOOP; END $upgrade$;
CREATE TABLE restaurant.families(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,site_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true,version int NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(tenant_id,site_id,id),UNIQUE(tenant_id,site_id,code),FOREIGN KEY(tenant_id,site_id) REFERENCES restaurant.sites(tenant_id,id));
CREATE TABLE restaurant.products(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,site_id uuid NOT NULL,family_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,price_cents int NOT NULL CHECK(price_cents BETWEEN 0 AND 100000000),active boolean NOT NULL DEFAULT true,available boolean NOT NULL DEFAULT false,quantity int NOT NULL DEFAULT 0 CHECK(quantity BETWEEN 0 AND 1000000),version int NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(tenant_id,site_id,id),UNIQUE(tenant_id,site_id,code),FOREIGN KEY(tenant_id,site_id) REFERENCES restaurant.sites(tenant_id,id),FOREIGN KEY(tenant_id,site_id,family_id) REFERENCES restaurant.families(tenant_id,site_id,id));
CREATE TABLE restaurant.sectors(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,site_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true,version int NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(tenant_id,site_id,id),UNIQUE(tenant_id,site_id,code),FOREIGN KEY(tenant_id,site_id) REFERENCES restaurant.sites(tenant_id,id));
CREATE TABLE restaurant.dining_tables(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,site_id uuid NOT NULL,sector_id uuid NOT NULL,code text NOT NULL,capacity int NOT NULL CHECK(capacity BETWEEN 1 AND 100),x int CHECK(x BETWEEN 0 AND 10000),y int CHECK(y BETWEEN 0 AND 10000),active boolean NOT NULL DEFAULT true,version int NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(tenant_id,site_id,id),UNIQUE(tenant_id,site_id,code),FOREIGN KEY(tenant_id,site_id) REFERENCES restaurant.sites(tenant_id,id),FOREIGN KEY(tenant_id,site_id,sector_id) REFERENCES restaurant.sectors(tenant_id,site_id,id));
CREATE TABLE restaurant.attentions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,site_id uuid NOT NULL,table_id uuid NOT NULL,waiter_id uuid NOT NULL,waiter_name text NOT NULL,guests int NOT NULL CHECK(guests BETWEEN 1 AND 100),request_id uuid NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled')),opened_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz,cancel_reason text,consumption_count int NOT NULL DEFAULT 0 CHECK(consumption_count>=0),UNIQUE(tenant_id,site_id,id),UNIQUE(tenant_id,site_id,request_id),FOREIGN KEY(tenant_id,site_id) REFERENCES restaurant.sites(tenant_id,id),FOREIGN KEY(tenant_id,site_id,table_id) REFERENCES restaurant.dining_tables(tenant_id,site_id,id),FOREIGN KEY(tenant_id,waiter_id) REFERENCES restaurant.users(tenant_id,id),CHECK((status='active' AND cancelled_at IS NULL AND cancel_reason IS NULL) OR (status='cancelled' AND cancelled_at IS NOT NULL AND length(trim(cancel_reason))>0 AND consumption_count=0)));
CREATE UNIQUE INDEX one_active_attention ON restaurant.attentions(tenant_id,site_id,table_id) WHERE status='active';
CREATE TABLE restaurant.quantity_adjustments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,site_id uuid NOT NULL,product_id uuid NOT NULL,actor_id uuid NOT NULL,previous_quantity int NOT NULL,new_quantity int NOT NULL,previous_version int NOT NULL,reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 240),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,site_id,product_id) REFERENCES restaurant.products(tenant_id,site_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES restaurant.users(tenant_id,id));
CREATE TABLE restaurant.operation_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,site_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,entity_id uuid NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,site_id) REFERENCES restaurant.sites(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES restaurant.users(tenant_id,id));
DO $scope$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['families','products','sectors','dining_tables','attentions','quantity_adjustments','operation_events'] LOOP
EXECUTE format('ALTER TABLE restaurant.%I ENABLE ROW LEVEL SECURITY',tab);
EXECUTE format('ALTER TABLE restaurant.%I FORCE ROW LEVEL SECURITY',tab);
EXECUTE format('CREATE POLICY tenant_scope ON restaurant.%I USING (tenant_id=nullif(current_setting(''restaurant.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''restaurant.tenant_id'',true),'''')::uuid)',tab);
END LOOP; END $scope$;
GRANT SELECT,INSERT,UPDATE ON restaurant.families,restaurant.products,restaurant.sectors,restaurant.dining_tables,restaurant.attentions TO restaurante_runtime;
GRANT SELECT,INSERT ON restaurant.quantity_adjustments,restaurant.operation_events TO restaurante_runtime;
INSERT INTO restaurant.metadata VALUES('patch004','catalog-and-tables');
